import { readChoice } from './privacy-choice.js'
export const PIXEL_ID = '1472369584750454'
const SENT_KEY = 'limetta_meta_sent'
const PUBLIC_PAGES = new Map([['/', 'accueil'], ['/index.html','accueil'], ['/rdv','rdv'], ['/rendez-vous.html','rdv'], ['/confidentialite.html','confidentialite']])
export function pageName(pathname) { return PUBLIC_PAGES.get(pathname) || null }
export function clearMetaCookies(doc, hostname) {
  // Only our first-party cookies can be deleted; cookies on facebook.com belong to Meta.
  const domains = ['', hostname, '.' + hostname]
  if (hostname.endsWith('.cuisines-limetta.com')) domains.push('cuisines-limetta.com','.cuisines-limetta.com')
  for (const name of ['_fbp','_fbc']) for (const domain of domains) for (const cookiePath of ['/','/rdv','/meta-pixel.html']) {
    doc.cookie = `${name}=; Max-Age=0; Path=${cookiePath}; SameSite=Lax${domain ? '; Domain='+domain : ''}`
  }
}
export function createMetaPixel({ win=window, doc=document, storage, now=Date.now, enabled=false }) {
  let script, ready=false, generation=0, pageSent=false, approvedReceipt=null, initialized=false
  const pending=new Map(), memorySent=new Set()
  const page=pageName(win.location.pathname)
  const consent=()=>readChoice(storage,now())
  const allowed=()=>Boolean(enabled && page && consent()?.advertising && consent()?.receipt===approvedReceipt)
  function sent() {
    try { const value=JSON.parse(storage.getItem(SENT_KEY)); return Array.isArray(value) ? value.filter(row=>typeof row?.id==='string' && now()-row.at<180*86400000).slice(-200) : [] } catch { return [] }
  }
  function send(eventId) {
    if (!ready || !allowed()) return
    if (memorySent.has(eventId) || sent().some(row=>row.id===eventId)) return
    // Mark before dispatch to avoid duplicate browser submissions; delivery itself is not guaranteed.
    memorySent.add(eventId)
    try { storage.setItem(SENT_KEY,JSON.stringify([...sent(),{id:eventId,at:now()}].slice(-200))) } catch {}
    win.fbq('trackSingle',PIXEL_ID,'Schedule',{page_name:page},{eventID:eventId})
  }
  function stop() {
    generation++;ready=false;approvedReceipt=null;pending.clear()
    if (win.fbq) {
      if (Array.isArray(win.fbq.queue)) win.fbq.queue.length=0
      win.fbq('consent','revoke')
    }
    clearMetaCookies(doc,win.location.hostname)
    try { storage.removeItem(SENT_KEY) } catch {}
  }
  function start(receipt) {
    approvedReceipt=receipt
    if (!allowed()) { stop();return }
    if (ready) return
    const current=++generation
    const clickId=new URLSearchParams(win.location.search || '').get('fbclid')
    const safeClick=typeof clickId==='string' && /^[A-Za-z0-9_-]{10,500}$/.test(clickId) ? clickId : null
    // Drop arbitrary query strings before loading any vendor SDK, after internal capture.
    if(win.location.search||win.location.hash)win.history.replaceState(win.history.state,'',win.location.pathname+(safeClick?'?fbclid='+encodeURIComponent(safeClick):''))
    function activate() {
      if(current!==generation||!allowed())return
      ready=true
      win.fbq('consent','grant')
      win.fbq('set','autoConfig',false,PIXEL_ID)
      if(!initialized){win.fbq('init',PIXEL_ID);initialized=true}
      if(!pageSent){pageSent=true;win.fbq('trackSingle',PIXEL_ID,'PageView',{page_name:page})}
      for(const [id,receipt] of pending)if(receipt===consent()?.receipt)send(id)
      pending.clear()
    }
    if(script){script.onload=activate;if(win.fbq.callMethod)activate();return}
    // Official bootstrap in the public document, only after the acknowledged consent.
    // No matching data, form values, URL-derived events or automatic events are added.
    const fbq=win.fbq=function(){fbq.callMethod?fbq.callMethod.apply(fbq,arguments):fbq.queue.push(arguments)}
    win._fbq=fbq;fbq.push=fbq;fbq.loaded=true;fbq.version='2.0';fbq.queue=[]
    script=doc.createElement('script');script.async=true;script.src='https://connect.facebook.net/en_US/fbevents.js';script.referrerPolicy='no-referrer'
    script.onload=activate;script.onerror=()=>{stop();script.remove();script=null}
    doc.head.append(script)
  }
  win.addEventListener('storage',event=>{ if (!allowed()) stop() })
  doc.addEventListener('visibilitychange',()=>{if(!allowed())stop()})
  const expiryTimer=win.setInterval(()=>{if(approvedReceipt&&!allowed())stop()},1000)
  win.addEventListener('pagehide',stop)
  return { start, stop, schedule(id, originalConsent) {
    if (!allowed() || originalConsent?.receipt!==consent()?.receipt || !/^[a-f0-9-]{36}$/i.test(id || '')) return
    if (ready) send(id);else pending.set(id,originalConsent.receipt)
  }, destroy(){stop();win.clearInterval(expiryTimer)} }
}
